[11263] = {id=11263,name="Dealing With Gjalerbron",level=10,requiredLevel=10,faction="horde",expansion=2,zoneID=495,mapID=117,description="My longrunners that have lived to return have informed me that the vrykul have awakened at their main fortress to the west. It is a forbidden place known as Gjalerbron. The longrunners tell me that the vrykul are performing strange rituals. We cannot allow this to continue. Are you willing to continue to assist us? Will you kill the vrykul at Gjalerbron before they finish whatever they are doing and attack us here?",starts={{npcID=24129,x=0.48,y=0.108,mapID=117}},ends={{npcID=24129,x=0.48,y=0.108,mapID=117}},coords={x=0.48,y=0.108,source="quest_giver",mapID=117},questType="standard"},
[11312] = {id=11312,name="The Frozen Glade",level=10,requiredLevel=10,faction="horde",expansion=2,zoneID=495,mapID=117,description="For generations, my people have told tales of frost nymphs cavorting in glades hidden away in the wilderness. I used to search for them as a child, against the advice of my parents, until I nearly froze to death. These days, it isn't necessary to comb the forests for them. They've decided to reveal themselves for reasons I can only guess, but I don't think the change can be ignored. Venture southeast to the Frozen Glade and seek out the nymphs, but beware; you will pass the Twisted Glade on your way.",starts={{npcID=24123,x=0.492,y=0.118,mapID=117}},ends={{npcID=24117,x=0.614,y=0.228,mapID=117}},coords={x=0.492,y=0.118,source="quest_giver",mapID=117},questType="standard"},
[11401] = {id=11401,name="Call the Headless Horseman",level=20,requiredLevel=20,faction="none",expansion=2,description="Many dreary candles adorn this pumpkin shrine, which grins, taunting...",questType="dungeon"},
