[11405] = {id=11405,name="Call the Headless Horseman",level=20,requiredLevel=20,faction="horde",expansion=2,description="Many dreary candles adorn this pumpkin shrine, which grins, taunting...",questType="dungeon"},
[11519] = {id=11519,name="The Lost Shield of the Aesirites",level=10,requiredLevel=10,faction="both",expansion=2,zoneID=495,mapID=117,description="If you listen real close you can hear cannon fire coming from the northeast. That's Captain Ellis 's ship, Sister Mercy. Thing is, Ellis and his entire crew were killed 'bout a month ago. Ghost ship... If it's info you be wantin' 'bout the shield, Ellis is the man to ask. Sister Mercy docks on the small island between here and Sorlof's Strand to pick up more souls for the ship's crew 'bout once every five minutes. There be no shortage of souls 'round these parts...",starts={{npcID=24539,x=0.35,y=0.808,mapID=117}},ends={{npcID=24910,x=0.372,y=0.748,mapID=117}},coords={x=0.35,y=0.808,source="quest_giver",mapID=117},questType="standard"},
[11528] = {id=11528,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="alliance",expansion=2,zoneID=1637,mapID=85,starts={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},ends={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[11691] = {id=11691,name="Summon Ahune",level=1,requiredLevel=1,faction="none",expansion=2,description="I and my Shamans have gathered our powers for the coming battle with the Lord of Frost. , you will be the fist of the Earthmother. Take this magma totem. Use it against the Ice Stone, to the northeast. Ahune is channeling his power through this stone; it is our hope that the totem will disrupt him and cut off his link to the elemental planes. If fortune is with us, then, perhaps, we can defeat him. Prepare yourself, . If Ahune comes to face us, then his fury will be great.",questType="dungeon"},
