[13604] = {id=13604,name="Archivum Data Disc",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4273,mapID=114,description="This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections. Engraved along its edge, bold runes spell out the word \"ARCHIVUM.\" There must be a device inside Ulduar capable of reading the disc.",ends={{npcID=194555,mapID=114},{npcID=194555,mapID=114}},questType="raid"},
[13622] = {id=13622,name="Ancient History",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4273,mapID=114,description="The pieces fit together to form an elegant hammer. Its construction appears to be at least partially Titan in nature. The console inside the Archivum might have some information regarding this artifact.",ends={{npcID=194555,mapID=114},{npcID=194555,mapID=114}},questType="raid"},
[13817] = {id=13817,name="Heroic: Archivum Data Disc",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4273,mapID=114,description="This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections. Engraved along its edge, bold runes spell out the word \"ARCHIVUM.\" There must be a device inside Ulduar capable of reading the disc.",ends={{npcID=194555,mapID=114},{npcID=194555,mapID=114}},questType="raid"},
