[13959] = {id=13959,name="Back To The Orphanage",level=10,requiredLevel=10,faction="both",expansion=2,zoneID=4395,mapID=118,description="We had the best time with you, . We wish you could be our now, but you have to take us back to Orphan Matron Aria in Dalaran. Maybe you could come visit us again sometime? We loved meeting Winterfin hatchlings and getting to see the dragon queen. No one will believe us when we say we met a Great One! We going to miss you, . We promise to write letter sometime, oki?",questType="standard"},
[13960] = {id=13960,name="Back To The Orphanage",level=10,requiredLevel=10,faction="both",expansion=2,zoneID=4395,mapID=118,description="Know what? You not so bad after all, . You take Kekek a lot of fun places. Kekek meet a lot of new friends and do things no other pup get to do. You, and Hemet Nesingwary, and Snowfall Glade pups all new best friends. Maybe sometime you bring Kekek that green hills book? Kekek promise to write sometimes, too, tell you how things go. Maybe even be nice to big-tongue kids sometimes. Kekek gotta go back to orphan-lady Aria now, back in purple human city.",questType="standard"},
[13966] = {id=13966,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="none",expansion=2,questType="standard"},
[14203] = {id=14203,name="Waterlogged Recipe",level=10,requiredLevel=10,faction="alliance",expansion=2,zoneID=4395,mapID=118,description="This appears to be the remains of a mixture for potent wine. Perhaps the proprietor of One More Glass in Dalaran would be interested in it....",questType="standard"},
[24429] = {id=24429,name="A Most Puzzling Circumstance",level=30,requiredLevel=30,faction="horde",expansion=2,zoneID=2159,mapID=84,description="You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Arnak Fireblade .",ends={{npcID=3216,x=0.5,y=0.59,mapID=85},{npcID=3216,x=0.588,y=0.54,mapID=85}},questType="standard"},
