[28649] = {id=28649,name="A Special Surprise",level=8,requiredLevel=8,faction="alliance",expansion=2,zoneID=4298,mapID=124,description="We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, . Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing. I was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty worgen in there that I think you'll take great pleasure in executing.",starts={{npcID=29053,x=0.528,y=0.814,mapID=124}},ends={{npcID=29053,x=0.528,y=0.814,mapID=124}},coords={x=0.528,y=0.814,source="quest_giver",mapID=124},questType="standard"},
